import sqlite3
c=sqlite3.connect('inputs/db/california_schools.sqlite')
for n,q in {
'q12 rows': '''SELECT t.cds,t.sname,t.NumGE1500,t.NumTstTakr,1.0*t.NumGE1500/t.NumTstTakr rate,1.0*f.\"Free Meal Count (Ages 5-17)\"/f.\"Enrollment (Ages 5-17)\" frate FROM satscores t JOIN frpm f ON t.cds=f.CDSCode WHERE 1.0*t.NumGE1500/t.NumTstTakr>0.3 ORDER BY frate DESC LIMIT 10''',
'q24 blank names': '''SELECT COUNT(*), SUM(f.\"School Name\" IS NULL), SUM(trim(f.\"School Name\")='') FROM frpm f JOIN satscores t ON f.CDSCode=t.cds WHERE 1.0*f.\"Free Meal Count (K-12)\"/f.\"Enrollment (K-12)\">0.1 AND t.NumGE1500>0''',
'q62 details': '''SELECT f.CDSCode,f.\"School Name\",f.\"Free Meal Count (K-12)\",f.\"Enrollment (K-12)\",f.\"Free Meal Count (K-12)\"*100/f.\"Enrollment (K-12)\" p FROM frpm f JOIN schools s ON f.CDSCode=s.CDSCode WHERE s.County='Los Angeles' AND s.Charter=0 AND f.\"Free Meal Count (K-12)\"*100/f.\"Enrollment (K-12)\" < 0.18''',
'q28 details': '''SELECT s.School,s.DOC,f.\"Enrollment (K-12)\"-f.\"Enrollment (Ages 5-17)\" diff FROM frpm f JOIN schools s ON f.CDSCode=s.CDSCode WHERE s.FundingType='Locally funded' ORDER BY diff DESC''',
}.items():
 print('\\n--',n)
 try:
  rows=list(c.execute(q)); print('rows',len(rows))
  for r in rows[:20]: print(r)
 except Exception as e: print('ERR',e)
PY"

